paths = set()
with open("/data/app.log") as f:
    for line in f:
        parts = line.rstrip("\r\n").split(" ")
        if len(parts) == 5:
            paths.add(parts[2])

def norm(raw):
    # drop query string
    p = raw.split("?", 1)[0]
    # drop one trailing / except root /
    if len(p) > 1 and p.endswith("/"):
        p = p[:-1]
    # replace every path segment made only of digits with :id
    segments = p.split("/")
    new_segments = []
    for s in segments:
        if s.isdigit():
            new_segments.append(":id")
        else:
            new_segments.append(s)
    return "/".join(new_segments)

norm_paths = set(norm(p) for p in paths)
print("Normalized paths:")
for np in sorted(norm_paths):
    print(" ", repr(np))
